{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"RSO no-fault eviction relocation assistance","requirement":"For a no-fault eviction of an RSO unit, the landlord must file a Declaration of Intent to Evict with LAHD before serving notice and pay relocation assistance within 15 days; RSO demolition evictions are Ellis Act evictions under LAMC 151.22-151.28.","key_value":"$11,000-$27,400 per unit (July 1, 2026 - June 30, 2027)","coverage_conditions":"Tenants displaced by a no-fault eviction from rental units covered by the Rent Stabilization Ordinance in the City of Los Angeles.","applicability":{"conditions":[],"per_tenancy":"No-fault eviction of a tenant from an RSO-covered unit; the amount depends on whether the tenant is eligible or qualified, on tenant income, and on length of tenancy","coverage_quotes":[]},"exemptions":"Mom and Pop properties (four or fewer rental units) may pay reduced relocation assistance for good-faith owner, family or manager occupancy evictions; payment exemptions include replacing a resident manager and hazardous conditions from a natural disaster not caused by landlord negligence; landlord may offset accumulated rent.","penalty":"An eviction without the filed landlord declaration is a violation of the RSO or JCO; the tenant may raise non-payment as an affirmative defense, file a complaint with LAHD, or seek a private right of action.","effective_date":"2026-07-01","valid_through":"2027-06-30","citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. § 151.00 et seq.)","quoted_span":"All tenant not- at-fault evictions require payment of relocation assistance and the filing of a Declaration of Intent to Evict form with the Los Angeles Housing Department (LAHD) before evicting tenants from units covered by the Rent Stabilization Ordinance (RSO) or the Just Cause Ordinance (JCO).","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"JCO no-fault eviction relocation assistance","requirement":"A landlord ending a tenancy for a no-fault reason under the Just Cause Ordinance must file a Declaration of Intent to Evict with LAHD and pay relocation assistance within 15 days of serving notice; a single-family dwelling owned by a natural person is paid one month's rent.","key_value":"one month's rent for single-family dwellings owned by a natural person; $11,000-$27,400 per unit otherwise (July 1, 2026 - June 30, 2027)","coverage_conditions":"Tenants displaced by a no-fault eviction from rental units covered by the Just Cause Ordinance in the City of Los Angeles.","applicability":{"conditions":[],"per_tenancy":"No-fault eviction of a tenant from a JCO-covered unit; the one month's rent payment applies where the unit is a single-family dwelling whose owner is a natural person owning no more than four dwelling units","coverage_quotes":[]},"exemptions":"Payment exemptions include evicting a resident manager to replace him or her with another resident manager and evictions required by hazardous conditions caused by a natural disaster not caused by landlord negligence.","penalty":"Non-payment of relocation assistance may be raised as an affirmative defense in the eviction action; the tenant may file a complaint with LAHD or seek a private right of action.","effective_date":"2026-07-01","valid_through":"2027-06-30","citation":"Los Angeles Just Cause Ordinance (L.A.M.C. § 165.00 et seq.)","quoted_span":"When the residential real property is a single-family dwelling subject to the JCO and the owner is a natural person, including natural persons who hold properties in a trust or registered legal entity controlled by that natural person, who owns no more than four dwelling units and a single-family home on a separate lot in the City of Los Angeles: one month's rent","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Resident Protections Ordinance relocation for demolition for new construction","requirement":"An owner demolishing a Protected Unit for new construction within five years of filing the withdrawal notice or declaration must follow the RPO relocation options and pay the highest of State and City relocation amounts.","key_value":"highest of State (HCA) or City relocation amounts; penalties from $250,000 per displaced unit","coverage_conditions":"Only Protected Units demolished for the purpose of new construction, including all RSO units and units rent-restricted or rented to lower income households within the past five years.","applicability":{"conditions":[{"type":"other","text":"Only Protected Units demolished for the purpose of new construction are covered"}],"per_tenancy":"Landlord terminates a tenancy to demolish a Protected Unit for new construction within 5 years of filing the notice","coverage_quotes":["The RPO only applies to Protected Units that will be demolished for the purpose of new construction."]},"exemptions":"Units that are not Protected Units, or that are not occupied by a lower income tenant, remain governed by the regular RSO or JCO relocation rules.","penalty":"Financial penalties starting at $250,000 per displaced unit and withholding of LAHD permit clearances.","effective_date":"2025-02-11","valid_through":null,"citation":"Los Angeles Resident Protections Ordinance (Ordinances #188481 and #188482)","quoted_span":"Failure to comply with the RPO may result in financial penalties starting at $250,000 per displaced unit and withholding of LAHD permit clearances.","interaction":"Owner must pay the higher of State Housing Crisis Act amounts or City relocation amounts.","relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
